// The wire constants `crates/fathom-wasm/src/protocol.rs` and
// `crates/fathom-wasm/src/lib.rs` define, hand-copied because nothing
// generates this TypeScript file yet (ADR-0052 §1: "Face and error codes are
// generated from Rust, never typed twice").
//
// `client/src/engine/protocol.generated.json` now exists — generated by
// `cargo test -p fathom-wasm --test protocol_generated -- --ignored
// --nocapture` — and `protocol.constants.generated.test.ts` checks this
// file's numbers against it on every run, not trusted forever: a mismatch
// fails loudly there, not here, because a hand-copied table is exactly the
// kind of thing that drifts quietly. Keep the two in step by hand until this
// file itself is generated; a `grep` against `protocol.rs`/`lib.rs` is the
// re-check either way.

/** `lib.rs`'s opcode table (41 §3.7): stable forever, a new call is a new
 * opcode. 28–30 are ADR-0052 §4's three doors, implemented on the Rust side. */
export const OPCODES = {
  OP_INIT: 1,
  OP_QUERY: 4,
  OP_ESTATE_DEMO: 11,
  OP_INV_ROWS: 12,
  OP_ELEMENT: 13,
  OP_EQUIPMENT: 14,
  OP_PASTE: 15,
  OP_EQUIP_ADD: 16,
  OP_FIELD_SET: 17,
  OP_ELEMENT_REMOVE: 18,
  OP_DIAGRAM: 19,
  OP_DICT: 20,
  OP_PLACE: 21,
  OP_RACK_PLACE: 22,
  OP_RACK_ELEVATION: 23,
  OP_LINK: 24,
  OP_FINDINGS: 25,
  OP_INSIDE: 26,
  OP_CABLE: 27,
  /** ADR-0052 §4, door one: load the plain face into the module. */
  OP_LOAD_PLAIN: 28,
  /** ADR-0052 §4, door two: export the plain face back out. */
  OP_EXPORT_PLAIN: 29,
  /** ADR-0052 §4, door three: paste under a placed device. */
  OP_PASTE_INTO: 30,
} as const;

