/** The FDLT reply header (`protocol.rs`'s `header()`, `HEADER_LEN`). */
export const REPLY_MAGIC = [0x46, 0x44, 0x4c, 0x54]; // "FDLT"
export const REPLY_VERSION = 1;
export const HEADER_LEN = 16;

/** Record kinds, and the fixed stride that goes with each. Kind 3 (finder
 * rows) is named for completeness of the table but is not decoded by this
 * client slice — the drawer never sends `OP_QUERY`. */
export const KIND_ERROR = 0;
export const KIND_FINDER_ROW = 3;
export const KIND_FACE_ROW = 5;

export const ERROR_STRIDE = 28;
export const FINDER_ROW_STRIDE = 88;
export const FACE_ROW_STRIDE = 72;
export const FACE_SLOTS = 8;

/** `dictframe.rs`'s role byte: which half of an `OP_DICT` file this is. */
export const DICT_ROLE_SOURCE = 0; // ROLE_DICT_SOURCE
export const DICT_ROLE_FIELD_KEYS = 1; // ROLE_FIELD_KEYS

type NumberTable = Record<string, number>;

function reverseLookup(table: NumberTable): Map<number, string> {
  const out = new Map<number, string>();
  for (const [name, value] of Object.entries(table)) {
    out.set(value, name);
  }
  return out;
}

const FACE_NAMES_BY_VALUE = reverseLookup(FACES);
const ERROR_NAMES_BY_VALUE = reverseLookup(ERRORS);

/** The face role's name from the table above, for callers that want to say
 * which face a row is rather than carry the bare number (WO-08 §4.4's "keyed
 * by face name", not a name-to-key table re-derived per caller). */
export function faceName(role: number): string | undefined {
  return FACE_NAMES_BY_VALUE.get(role);
}

export function errorName(code: number): string | undefined {
  return ERROR_NAMES_BY_VALUE.get(code);
}
